"""MAHGIC presentation (brief §20-23): ONE class palette (Athlete = GOLD for every category), aura / energy-flow / streak / soft-impact
language instead of spheres, cones, hard rings; body pre-glow through the existing shader aura; hand glows as soft sprites."""
import os
HERE = os.path.dirname(os.path.abspath(__file__))
def patch(name, pairs):
    p = os.path.join(HERE, name); s = open(p, encoding='utf-8').read()
    for old, new in pairs:
        assert s.count(old) == 1, (name, old[:70], s.count(old)); s = s.replace(old, new)
    open(p, 'w', encoding='utf-8').write(s)

